installer-gui-script.script:
// Read a sysctl without letting a missing key abort the check. Keys are not
// uniformly present: hw.optional.arm64 does not exist on Intel, and
// sysctl.proc_translated does not exist outside Rosetta.
function ssoosshSysctl(key)
{
    try {
        var value = system.sysctl(key);
        return value ? String(value) : '';
    } catch (err) {
        return '';
    }
}

// Whether the hardware is Apple silicon, which is not the same question as
// what this process is running as. With hostArchitectures="x86_64" the
// installer is itself translated on Apple silicon, so anything reporting the
// process architecture reports Intel and would pass a check that should
// fail. Three independent signals, cheapest first:
//
//   sysctl.proc_translated    1 when the calling process is translated,
//                             which for this package means the host is
//                             Apple silicon
//   hw.optional.arm64         1 on Apple silicon hardware
//   machdep.cpu.brand_string  the physical CPU, "Apple M..." on Apple
//                             silicon, an Intel string otherwise
function ssoosshOnAppleSilicon()
{
    if (ssoosshSysctl('sysctl.proc_translated') == '1') {
        return true;
    }
    if (ssoosshSysctl('hw.optional.arm64') == '1') {
        return true;
    }
    return ssoosshSysctl('machdep.cpu.brand_string').indexOf('Apple') >= 0;
}

function ssoosshArchCheck()
{
    var want = '@HOSTARCH@';
    var have = ssoosshOnAppleSilicon() ? 'arm64' : 'x86_64';
    if (want == have) {
        return true;
    }
    my.result.title = 'Wrong package for this Mac';
    my.result.message = 'This is the @ARCHNAME@ build of the ssoossh client '
        + '(@HOSTARCH@), and this Mac is not @ARCHNAME@. Installing it would '
        + 'put a binary here that this Mac cannot run natively. Download the '
        + 'package for this Mac from the ssoossh @VERSION@ release and install '
        + 'that one instead.';
    my.result.type = 'Fatal';
    return false;
}
